function articleParts(topic) {
  const paragraphs = [
    `La question « ${topic.readingTitle} » occupe une place centrale dans l’analyse contemporaine. ${topic.problem} Une réponse sérieuse doit distinguer ce que les données montrent, le mécanisme proposé pour l’expliquer et l’implication concrète que l’on souhaite en tirer. Ces trois niveaux se soutiennent, mais ils ne sont pas interchangeables : un constat isolé ne prescrit pas directement une politique, et une intuition largement partagée ne prouve pas à elle seule une relation causale durable.`,
    topic.evidence,
    topic.mechanism,
    topic.method,
    topic.debate,
    topic.limits,
    topic.practice,
    `${topic.conclusion} En définitive, ${topic.response.charAt(0).toLowerCase() + topic.response.slice(1)} Cette conclusion reste révisable : elle vaut dans les limites des données, des institutions et des mesures étudiées. Pour le lecteur C2, l’enjeu consiste précisément à conserver ensemble la force d’un résultat et les conditions qui en bornent la portée, sans réduire l’incertitude à l’ignorance ni transformer une tendance générale en fatalité.`
  ];
  // Six reading cards keep the long C2 article manageable without cutting
  // sentences or duplicating content: 2 + 1 + 1 + 2 + 1 + 1 paragraphs.
  const groupSizes = [2, 1, 1, 2, 1, 1];
  let offset = 0;
  return groupSizes.map((size) => {
    const part = paragraphs.slice(offset, offset + size).join('\n\n');
    offset += size;
    return part;
  });
}

function readingQuestions(topic) {
  return topic.customQuestions.map((question) => ({
    prompt: question.prompt,
    correct: question.correct,
    distractors: question.distractors
  }));
}

module.exports = rawTopics.map((topic, index) => {
  const [grammar, purpose, rule] = grammarSequence[index];
  return {
    ...topic,
    grammar,
    purpose,
    rule,
    parts: articleParts(topic),
    questions: readingQuestions(topic)
  };
});
